def collate_multimodal_metadata(batch, sp_pad):
    """Derive MiniMax ViT metadata on CPU inside the VeOmni collator.

    Each ``grid_thw`` entry is one logical visual sample with ``t * h * w``
    tokens. An SP-padding tail, when present, is appended as a separate
    synthetic sequence so neither another sample nor padding can affect the
    real visual tokens through varlen attention.
    """
    md = {}
    for modality, grid_key, pad_key in (
        ("image", "image_grid_thw", "pixel_values"),
        ("video", "video_grid_thw", "pixel_values_videos"),
    ):
        grid = batch.get(grid_key)
        if grid is None:
            continue
        grid_list = grid.tolist() if torch.is_tensor(grid) else grid
        if not grid_list:
            continue

        md[f"{modality}_grid_thw_list"] = grid_list
        cu_seqlens = [0]
        max_seqlen = 0
        for t, h, w in grid_list:
            seq_len = t * h * w
            cu_seqlens.append(cu_seqlens[-1] + seq_len)
            max_seqlen = max(max_seqlen, seq_len)

        pad = sp_pad.get(pad_key, 0)
        if pad > 0:
            cu_seqlens.append(cu_seqlens[-1] + pad)
            max_seqlen = max(max_seqlen, pad)

        md[f"vit_{modality}_cu_seqlens"] = torch.tensor(
            cu_seqlens,
            dtype=torch.int32,
            device="cpu",
        )
        md[f"vit_{modality}_max_seqlen"] = max_seqlen
    if md:
        batch["multimodal_metadata"] = md


def _grid_thw_to_list(grid_thw, grid_thw_list):
    if grid_thw_list is not None:
        return grid_thw_list
    return grid_thw.tolist()


def _minimax_m3_indexer_project(indexer, hidden_states, position_embeddings):
    """Return the indexer's normed, rotated ``[B, S, G, D]`` queries and ``[B, S, 1, D]`` keys.

    This is the projection half of ``MiniMaxM3VLIndexer.forward``. On the packed
    training path, block selection runs in the MiniMax sparse attention
    operator after the Ulysses exchange instead.

    The indexer is not trained here: block selection is a top-k over discrete
    block scores and no indexer loss is computed, so its projections receive no
    gradient and keep their checkpoint values. MiniMax describes the indexer as
    distilled from full attention with a KL objective, but has not published how
    it is handled in post-training; add that objective here once it is known.
    """
    batch, q_len, _ = hidden_states.shape
    index_query = indexer.q_norm(indexer.q_proj(hidden_states).view(batch, q_len, -1, indexer.head_dim))
    index_key = indexer.k_norm(indexer.k_proj(hidden_states).view(batch, q_len, 1, indexer.head_dim))
    cos, sin = position_embeddings
    return apply_rotary_pos_emb(
        index_query,
        index_key,
        cos[..., : indexer.head_dim],
        sin[..., : indexer.head_dim],
        unsqueeze_dim=2,
    )


class MiniMaxM3VLSparseCacheLayer(DynamicLayer):
    _layer_type = "minimax_m3_sparse"

    def __init__(self, **kwargs):
        super().__init__()
        self.idx_keys: torch.Tensor | None = None

    def update_index(self, idx_k: torch.Tensor) -> torch.Tensor:
        """Append the new token's `idx_k` to the cache and return the full history."""
        self.idx_keys = idx_k if self.idx_keys is None else torch.cat([self.idx_keys, idx_k], dim=-2)
        return self.idx_keys

    def reorder_cache(self, beam_idx: torch.LongTensor) -> None:
        super().reorder_cache(beam_idx)
        if self.idx_keys is not None:
            self.idx_keys = self.idx_keys.index_select(0, beam_idx.to(self.idx_keys.device))

    def batch_repeat_interleave(self, repeats: int) -> None:
        super().batch_repeat_interleave(repeats)
        if self.idx_keys is not None:
            self.idx_keys = self.idx_keys.repeat_interleave(repeats, dim=0)

    def batch_select_indices(self, indices: torch.Tensor) -> None:
        super().batch_select_indices(indices)
        if self.idx_keys is not None:
            self.idx_keys = self.idx_keys[indices, ...]

    @deprecate_kwarg("max_length", new_name="tokens_to_remove", version="5.18")
    def crop(self, tokens_to_remove: int) -> None:
        super().crop(tokens_to_remove)
        if tokens_to_remove > 0:
            current_length = self.idx_keys.shape[-2]
            if tokens_to_remove >= current_length:
                return
            tokens_to_remove = current_length - tokens_to_remove
        if tokens_to_remove == 0:
            return
        self.idx_keys = self.idx_keys[..., : -abs(tokens_to_remove), :]


class MiniMaxM3VLSparseStaticCacheLayer(StaticLayer):
    _layer_type = "minimax_m3_sparse"

    def __init__(self, max_cache_len: int, **kwargs):
        super().__init__(max_cache_len)
        self.idx_keys: torch.Tensor | None = None
        # Tensor (not int) so it can be marked as a static address for cudagraphs, like `cumulative_length`.
        self.idx_cumulative_length = torch.tensor([0], dtype=int)

    def update_index(self, idx_k: torch.Tensor) -> torch.Tensor:
        """Write the new token's `idx_k` into the static buffer in place and return the whole buffer.

        The buffer's unfilled tail holds zeros, but those slots sit at key positions ahead of every
        current query, so the indexer's block- and token-level causal masking discards them — the
        returned `[B, 1, max_cache_len, D]` history is therefore safe to score against directly.
        """
        if self.idx_keys is None:
            self.idx_keys = torch.zeros(
                (idx_k.shape[0], idx_k.shape[1], self.max_cache_len, idx_k.shape[-1]),
                dtype=idx_k.dtype,
                device=idx_k.device,
            )
            self.idx_cumulative_length = self.idx_cumulative_length.to(idx_k.device)
            if not is_torchdynamo_compiling():
                torch._dynamo.mark_static_address(self.idx_keys)
                torch._dynamo.mark_static_address(self.idx_cumulative_length)

        kv_len = idx_k.shape[-2]
        cache_position = torch.arange(kv_len, device=self.idx_keys.device) + self.idx_cumulative_length
        self.idx_cumulative_length.add_(kv_len)
        try:
            self.idx_keys.index_copy_(2, cache_position, idx_k)
        except NotImplementedError:
            # Fallback for devices like MPS where index_copy_ might not be supported.
            self.idx_keys[:, :, cache_position] = idx_k
        return self.idx_keys

    def reset(self) -> None:
        super().reset()
        if self.idx_keys is not None:
            self.idx_keys.zero_()
        self.idx_cumulative_length.zero_()

    def reorder_cache(self, beam_idx: torch.LongTensor) -> None:
        super().reorder_cache(beam_idx)
        if self.idx_keys is not None:
            self.idx_keys = self.idx_keys.index_select(0, beam_idx.to(self.idx_keys.device))


